/**
 * Shopify admin analytics palette, measured from the native reports:
 * current period in blue, the comparison period pale and dashed, light
 * gridlines with a darker zero line, and grey 12px axis labels.
 */
export const CHART = {
  /** The current period's line. */
  primary: "#2c6ecb",
  /** Bars, funnel stages and ranked bars. */
  bar: "#4b8ff7",
  /** The previous period's line and bars. */
  comparison: "#a4c4f3",
  /** Funnel tracks and drop-off bands. */
  faded: "#dbe8fd",
  /** Gridlines and the empty donut ring. */
  grid: "#ebebeb",
  /** The zero line. */
  baseline: "#d4d4d4",
  axisText: "#616161",
  axisFontSize: 12,
  /** The hover guide line. */
  guide: "#8a8a8a",
  /** Donut slices, in order. */
  palette: ["#2c6ecb", "#4b8ff7", "#7fb0fa", "#b3d0fc", "#dbe8fd"],
} as const;

/** Axis labels use the admin's font, inherited from the page. */
export const CHART_FONT = "inherit";

/** Default chart height in px. */
export const CHART_HEIGHT = 220;

/** Height of the funnel's bar plot. */
export const FUNNEL_PLOT_HEIGHT = 180;

/** Of each funnel column, the share the solid bar takes; the rest is the connector. */
export const FUNNEL_BAR_SHARE = 0.56;

/** Hover card width in px. */
export const TOOLTIP_WIDTH = 200;

import { BlockStack, Grid, Page } from "@xco-agency/corex-ui";
import { ChartCard } from "../partials/ChartCard";
import { ColumnChart } from "../partials/ColumnChart";
import { DonutChart } from "../partials/DonutChart";
import { FunnelChart } from "../partials/FunnelChart";
import { HorizontalBarList } from "../partials/HorizontalBarList";
import { LineChart } from "../partials/LineChart";
import { Sparkline } from "../partials/Sparkline";
import { percentChange, sum } from "../utils";
import {
  FUNNEL_STAGES,
  ORDERS_14,
  SALES,
  SALES_BY_CHANNEL,
  SESSIONS,
  TOP_LOCATIONS,
} from "./sampleData";

// All copy and formatting is passed in: swap these for your i18n and locale.
const number = new Intl.NumberFormat("en-US");
const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const shortDate = (iso: string) =>
  iso
    ? new Date(`${iso}T00:00:00Z`).toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        timeZone: "UTC",
      })
    : "";
const rangeLabel = (dates: string[]) =>
  dates.length
    ? `${shortDate(dates[0] ?? "")} – ${shortDate(dates[dates.length - 1] ?? "")}`
    : "";

export function AnalyticsChartsExample() {
  const sessionsTotal = sum(SESSIONS.current);
  const sessionsPrevious = SESSIONS.previous ? sum(SESSIONS.previous) : null;
  const salesTotal = sum(SALES.current);
  const salesPrevious = SALES.previous ? sum(SALES.previous) : null;
  const ordersTotal = sum(ORDERS_14.current);
  const ordersPrevious = ORDERS_14.previous ? sum(ORDERS_14.previous) : null;

  return (
    <Page heading="Analytics">
      <BlockStack gap="base">
        <Grid columns={{ xs: 1, md: 2 }} gap="base">
          <ChartCard
            title="Sessions"
            definition="Visits to your online store in the selected period."
            value={number.format(sessionsTotal)}
            change={percentChange(sessionsTotal, sessionsPrevious)}
          >
            <LineChart
              ariaLabel={`Sessions, ${rangeLabel(SESSIONS.dates)}`}
              dates={SESSIONS.dates}
              formatValue={(n) => number.format(n)}
              formatTick={(n) => compact.format(n)}
              formatDate={shortDate}
              series={[
                {
                  id: "current",
                  label: rangeLabel(SESSIONS.dates),
                  values: SESSIONS.current,
                  dates: SESSIONS.dates,
                },
                ...(SESSIONS.previous
                  ? [
                      {
                        id: "previous",
                        label: rangeLabel(SESSIONS.previousDates),
                        values: SESSIONS.previous,
                        dates: SESSIONS.previousDates,
                        dashed: true,
                      },
                    ]
                  : []),
              ]}
            />
          </ChartCard>

          <ChartCard
            title="Orders"
            definition="Orders placed per day, against the two weeks before."
            value={number.format(ordersTotal)}
            change={percentChange(ordersTotal, ordersPrevious)}
          >
            <ColumnChart
              ariaLabel={`Orders per day, ${rangeLabel(ORDERS_14.dates)}`}
              label={rangeLabel(ORDERS_14.dates)}
              comparisonLabel={rangeLabel(ORDERS_14.previousDates)}
              comparisonDates={ORDERS_14.previousDates}
              data={ORDERS_14.dates.map((date, i) => ({
                date,
                value: ORDERS_14.current[i] ?? 0,
                comparison: ORDERS_14.previous?.[i],
              }))}
              formatValue={(n) => number.format(n)}
              formatDate={shortDate}
            />
          </ChartCard>
        </Grid>

        <ChartCard
          title="Conversion rate breakdown"
          definition="How many sessions reached each step of the purchase."
          value="3.2%"
          change={0.4}
        >
          <FunnelChart ariaLabel="Conversion rate breakdown" stages={FUNNEL_STAGES} />
        </ChartCard>

        <Grid columns={{ xs: 1, md: 3 }} gap="base">
          <ChartCard
            title="Sessions by location"
            definition="Top countries by sessions in the selected period."
          >
            <HorizontalBarList ariaLabel="Sessions by location" items={TOP_LOCATIONS} />
          </ChartCard>

          <ChartCard
            title="Sales by channel"
            definition="Gross sales split by the channel the order came from."
          >
            <DonutChart
              ariaLabel="Sales by channel"
              total={money.format(sum(SALES_BY_CHANNEL.map((s) => s.value)))}
              totalLabel="Total"
              slices={SALES_BY_CHANNEL}
            />
          </ChartCard>

          <ChartCard
            title="Total sales"
            definition="Gross sales minus discounts and returns."
            value={money.format(salesTotal)}
            change={percentChange(salesTotal, salesPrevious)}
          >
            <Sparkline
              ariaLabel="Total sales trend"
              values={SALES.current}
              width={240}
              height={48}
            />
          </ChartCard>
        </Grid>
      </BlockStack>
    </Page>
  );
}

import type { BarListItemType, DonutSliceType, FunnelStageType } from "../types";
import { dayRange, periodSeries } from "../utils";

/** Deterministic demo rows: 60 days of sessions, orders and sales. */
const ALL_DAYS = dayRange("2026-09-15", "2026-11-13");

export const DAILY_ROWS = ALL_DAYS.map((date, i) => {
  // Seeded noise plus a weekly rhythm, so the demo looks like real traffic.
  const noise = ((i * 9301 + 49297) % 233280) / 233280 - 0.5;
  const weekly = [0.92, 1, 1.04, 1.02, 1.08, 1.18, 0.96][i % 7] ?? 1;
  const growth = 1 + i / 90;
  const sessions = Math.round(420 * growth * weekly * (1 + noise * 0.35));
  const orders = Math.round(sessions * (0.026 + (noise + 0.5) * 0.012));
  return { date, sessions, orders, sales: orders * 46 };
});

export const RANGE = {
  previousFrom: "2026-09-15",
  currentFrom: "2026-10-15",
  to: "2026-11-13",
};

export const SESSIONS = periodSeries(DAILY_ROWS, RANGE, (row) => row.sessions);
export const SALES = periodSeries(DAILY_ROWS, RANGE, (row) => row.sales);

/** The last two weeks of orders, with the two weeks before as comparison. */
export const ORDERS_14 = periodSeries(
  DAILY_ROWS,
  { previousFrom: "2026-10-17", currentFrom: "2026-10-31", to: "2026-11-13" },
  (row) => row.orders,
);

