import { useState, type KeyboardEvent, type PointerEvent } from "react";

export type ActiveIndexPropsType = {
  tabIndex: number;
  onPointerMove: (event: PointerEvent<SVGSVGElement>) => void;
  onPointerLeave: () => void;
  onFocus: () => void;
  onBlur: () => void;
  onKeyDown: (event: KeyboardEvent<SVGSVGElement>) => void;
};

/**
 * Hover and keyboard focus over a chart's points: the pointer picks the
 * nearest point, and with the chart focused the arrow keys (Home / End)
 * move between points, so every tooltip is reachable without a mouse.
 * Escape hides the tooltip.
 */
export function useActiveIndex(
  count: number,
  indexAt: (x: number) => number,
): { active: number | null; props: ActiveIndexPropsType } {
  const [active, setActive] = useState<number | null>(null);
  const clamp = (i: number) => Math.min(Math.max(i, 0), count - 1);

  return {
    active: active == null || count === 0 ? null : clamp(active),
    props: {
      tabIndex: count > 0 ? 0 : -1,
      onPointerMove: (event) => {
        const box = event.currentTarget.getBoundingClientRect();
        const scale =
          box.width > 0
            ? event.currentTarget.viewBox?.baseVal?.width / box.width || 1
            : 1;
        setActive(clamp(indexAt((event.clientX - box.left) * scale)));
      },
      onPointerLeave: () => setActive(null),
      onFocus: () => setActive((current) => current ?? count - 1),
      onBlur: () => setActive(null),
      onKeyDown: (event) => {
        const moves: Record<string, (i: number) => number> = {
          ArrowRight: (i) => i + 1,
          ArrowUp: (i) => i + 1,
          ArrowLeft: (i) => i - 1,
          ArrowDown: (i) => i - 1,
          Home: () => 0,
          End: () => count - 1,
        };
        const move = moves[event.key];
        if (move) {
          event.preventDefault();
          setActive((current) => clamp(move(current ?? count - 1)));
        } else if (event.key === "Escape") {
          setActive(null);
        }
      },
    },
  };
}

import { useEffect, useRef, useState, type RefObject } from "react";

/**
 * The width of the element a chart draws in, kept current with a
 * ResizeObserver. Server render and the first client render use
 * `fallback`, so the markup matches; the real width follows on mount.
 */
export function useChartWidth<T extends HTMLElement>(
  fallback = 640,
): [RefObject<T>, number] {
  const ref = useRef<T>(null);
  const [width, setWidth] = useState(fallback);

  useEffect(() => {
    const element = ref.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const update = () => {
      const next = Math.round(element.getBoundingClientRect().width);
      if (next > 0) setWidth(next);
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  return [ref, width];
}

export * from "./types";
export * from "./constants";
export * from "./utils";
export { useActiveIndex } from "./hooks/useActiveIndex";
export type { ActiveIndexPropsType } from "./hooks/useActiveIndex";
export { useChartWidth } from "./hooks/useChartWidth";
export { YAxisGrid, XAxisLabels } from "./partials/Axes";
export { ChangeIndicator } from "./partials/ChangeIndicator";
export { ChartCard } from "./partials/ChartCard";
export { ChartLegend, ChartTooltip, SeriesMarker } from "./partials/ChartTooltip";
export { ColumnChart } from "./partials/ColumnChart";
export { DonutChart } from "./partials/DonutChart";
export { FunnelChart } from "./partials/FunnelChart";
export { HorizontalBarList } from "./partials/HorizontalBarList";
export { LineChart } from "./partials/LineChart";
export { Sparkline } from "./partials/Sparkline";
export { AnalyticsChartsExample } from "./examples/AnalyticsChartsExample";

import { CHART, CHART_FONT } from "../constants";
import type { XAxisLabelsPropsType, YAxisGridPropsType } from "../types";

/** Horizontal gridlines with their value labels, Shopify style. */
export function YAxisGrid({
  ticks,
  max,
  left,
  right,
  top,
  plotHeight,
  format,
}: YAxisGridPropsType) {
  return (
    <g data-chart-y-axis="" aria-hidden>
      {ticks.map((tick) => {
        const y = top + plotHeight * (1 - tick / max);
        return (
          <g key={tick}>
            <line
              x1={left}
              x2={right}
              y1={y}
              y2={y}
              stroke={tick === 0 ? CHART.baseline : CHART.grid}
              strokeWidth={1}
              shapeRendering="crispEdges"
            />
            <text
              x={left - 8}
              y={y}
              dy="0.32em"
              textAnchor="end"
              fill={CHART.axisText}
              fontSize={CHART.axisFontSize}
              fontFamily={CHART_FONT}
            >
              {format(tick)}
            </text>
          </g>
        );
      })}
    </g>
  );
}

/** Date labels under the plot at the given x positions. */
export function XAxisLabels({ labels, y }: XAxisLabelsPropsType) {
  return (
    <g data-chart-x-axis="" aria-hidden>
      {labels.map((label, i) => (
        <text
          key={`${label.text}-${i}`}
          x={label.x}
          y={y}
          textAnchor={label.anchor ?? "middle"}
          fill={CHART.axisText}
          fontSize={CHART.axisFontSize}
          fontFamily={CHART_FONT}
        >
          {label.text}
        </text>
      ))}
    </g>
  );
}

import { Text } from "@xco-agency/corex-ui";
import type { ChangeIndicatorPropsType } from "../types";

/**
 * Shopify's change figure next to a value: "↗ 34%" in green, "↘ 12%" in
 * red, "→ 0%" when flat, and nothing without a previous period.
 */
export function ChangeIndicator({ pct, label }: ChangeIndicatorPropsType) {
  if (pct == null) return null;
  const up = pct > 0;
  const flat = pct === 0;
  return (
    <Text
      as="span"
      variant="bodySm"
      fontWeight="semibold"
      color={flat ? "subdued" : up ? "success" : "critical"}
      aria-label={label}
    >
      {`${flat ? "→" : up ? "↗" : "↘"} ${Math.abs(pct)}%`}
    </Text>
  );
}

import { BlockStack, Card, InlineStack, Text } from "@xco-agency/corex-ui";
import type { ChartCardPropsType } from "../types";
import { ChangeIndicator } from "./ChangeIndicator";

/**
 * Shopify's analytics card: the title (dotted underline, its definition on
 * hover), the headline value with its change, then the chart.
 */
export function ChartCard({
  title,
  definition,
  value,
  change,
  changeLabel,
  action,
  children,
}: ChartCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <BlockStack gap="small-300">
          <InlineStack justifyContent="space-between" alignItems="center" gap="small-200">
            <Text as="h3" variant="headingSm" tooltip={definition}>
              {title}
            </Text>
            {action}
          </InlineStack>
          {value != null && (
            <InlineStack gap="small-200" alignItems="center">
              <Text as="p" variant="headingLg">
                {value}
              </Text>
              <ChangeIndicator pct={change ?? null} label={changeLabel} />
            </InlineStack>
          )}
        </BlockStack>
        {children}
      </BlockStack>
    </Card>
  );
}

import { BlockStack, Box, InlineStack, Text } from "@xco-agency/corex-ui";
import { TOOLTIP_WIDTH } from "../constants";
import type {
  ChartLegendPropsType,
  ChartTooltipPropsType,
  SeriesMarkerPropsType,
} from "../types";

/** A coloured series marker: a dot, or a short dash for the comparison. */
export function SeriesMarker({ color, dashed = false }: SeriesMarkerPropsType) {
  return (
    <svg width="12" height="12" aria-hidden focusable="false">
      {dashed ? (
        <line
          x1="0"
          y1="6"
          x2="12"
          y2="6"
          stroke={color}
          strokeWidth="2"
          strokeDasharray="3 2"
        />
      ) : (
        <circle cx="6" cy="6" r="4" fill={color} />
      )}
    </svg>
  );
}

/**
 * Shopify's hover card: a white panel over the plot with the heading and
 * each series' value, beside the point and flipped left near the edge.
 */
export function ChartTooltip({
  x,
  containerWidth,
  heading,
  rows,
  children,
}: ChartTooltipPropsType) {
  const width = TOOLTIP_WIDTH;
  const left = x + 12 + width > containerWidth ? Math.max(0, x - 12 - width) : x + 12;
  return (
    <Box
      role="presentation"
      data-chart-tooltip=""
      position="absolute"
      insetBlockStart="4px"
      insetInlineStart={`${left}px`}
      zIndex={1}
      shadow="0 4px 12px rgba(0, 0, 0, 0.12), 0 0 0 1px rgba(0, 0, 0, 0.06)"
      style={{
        width,
        pointerEvents: "none",
        background: "#ffffff",
        borderRadius: 10,
        padding: "8px 12px",
      }}
    >
      <BlockStack gap="small-300">
        {heading && (
          <Text as="p" variant="bodySm" fontWeight="semibold">
            {heading}
          </Text>
        )}
        {rows.map((row) => (
          <InlineStack
            key={`${row.label}-${row.color}`}
            justifyContent="space-between"
            alignItems="center"
            gap="small-200"
            wrap={false}
          >
            <InlineStack gap="small-300" alignItems="center" wrap={false}>
              <SeriesMarker color={row.color} dashed={row.dashed} />
              <Text as="span" variant="bodySm" color="subdued">
                {row.label}
              </Text>
            </InlineStack>
            <Text as="span" variant="bodySm" fontWeight="semibold">
              {row.value}
            </Text>
          </InlineStack>
        ))}
        {children}
      </BlockStack>
    </Box>
  );
}

/** The legend under a chart: a marker and a label per series. */
export function ChartLegend({ items }: ChartLegendPropsType) {
  return (
    <InlineStack gap="base" justifyContent="center" alignItems="center">
      {items.map((item) => (
        <InlineStack key={item.label} gap="small-300" alignItems="center" wrap={false}>
          <SeriesMarker color={item.color} dashed={item.dashed} />
          <Text as="span" variant="bodySm" color="subdued">
            {item.label}
          </Text>
        </InlineStack>
      ))}
    </InlineStack>
  );
}

import { useId } from "react";
import { BlockStack, Box } from "@xco-agency/corex-ui";
import { CHART, CHART_HEIGHT } from "../constants";
import { useActiveIndex } from "../hooks/useActiveIndex";
import { useChartWidth } from "../hooks/useChartWidth";
import type { ColumnChartPropsType } from "../types";
import { labelWidth, valueScale, xLabelIndexes } from "../utils";
import { XAxisLabels, YAxisGrid } from "./Axes";
import { ChartLegend, ChartTooltip } from "./ChartTooltip";

/**
 * Shopify's column chart: blue bars from a labelled zero, light gridlines,
 * dates under the plot, an optional pale previous-period bar beside each,
 * and a hover / keyboard tooltip.
 */
export function ColumnChart({
  data,
  ariaLabel,
  label,
  comparisonLabel,
  comparisonDates,
  formatValue,
  formatTick = formatValue,
  formatDate,
  height = CHART_HEIGHT,
}: ColumnChartPropsType) {
  const titleId = useId();
  const [ref, width] = useChartWidth<HTMLElement>();
  const count = data.length;
  const compared = data.some((d) => d.comparison != null);
  const { ticks, max } = valueScale(data.flatMap((d) => [d.value, d.comparison ?? 0]));
  const marginLeft = Math.max(...ticks.map((t) => labelWidth(formatTick(t)))) + 8;
  const marginRight = 8;
  const top = 8;
  const bottom = 28;
  const plotHeight = height - top - bottom;
  const plotWidth = Math.max(width - marginLeft - marginRight, 10);
  const slot = plotWidth / Math.max(count, 1);
  const barWidth = Math.max(
    Math.min(slot * (compared ? 0.36 : 0.62), compared ? 14 : 28),
    1,
  );
  const center = (i: number) => marginLeft + slot * (i + 0.5);
  const barHeight = (v: number) => (plotHeight * (Number(v) || 0)) / max;
  const indexAt = (px: number) => Math.floor((px - marginLeft) / slot);
  const { active, props } = useActiveIndex(count, indexAt);
  const baseline = top + plotHeight;

  const labels = xLabelIndexes(count, width < 420 ? 4 : 6).map((i) => ({
    x: center(i),
    text: formatDate(data[i]?.date ?? ""),
  }));

  const bar = (cx: number, value: number, fill: string, key: string) => {
    const h = barHeight(value);
    if (h <= 0) return null;
    const r = Math.min(2, barWidth / 2, h);
    const x0 = cx - barWidth / 2;
    const y0 = baseline - h;
    // Rounded top corners only, as Shopify draws them.
    return (
      <path
        key={key}
        d={`M${x0},${baseline} V${y0 + r} Q${x0},${y0} ${x0 + r},${y0} H${x0 + barWidth - r} Q${x0 + barWidth},${y0} ${x0 + barWidth},${y0 + r} V${baseline} Z`}
        fill={fill}
      />
    );
  };

  const current = active != null ? data[active] : undefined;

  return (
    <BlockStack gap="small-100">
      <Box ref={ref} position="relative" style={{ width: "100%" }}>
        <svg
          width="100%"
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          role="group"
          aria-labelledby={titleId}
          style={{ display: "block", overflow: "visible", outline: "none" }}
          {...props}
        >
          <title id={titleId}>{ariaLabel}</title>
          <YAxisGrid
            ticks={ticks}
            max={max}
            left={marginLeft}
            right={marginLeft + plotWidth}
            top={top}
            plotHeight={plotHeight}
            format={formatTick}
          />
          {active != null && (
            <rect
              aria-hidden
              x={marginLeft + slot * active}
              y={top}
              width={slot}
              height={plotHeight}
              fill="#000000"
              fillOpacity={0.04}
            />
          )}
          <g data-chart-bars="">
            {data.map((d, i) => {
              const offset = compared ? barWidth / 2 + 1 : 0;
              return (
                <g key={`${d.date}-${i}`}>
                  {compared &&
                    d.comparison != null &&
                    bar(center(i) - offset, d.comparison, CHART.comparison, "previous")}
                  {bar(center(i) + offset, d.value, CHART.bar, "current")}
                </g>
              );
            })}
          </g>
          <XAxisLabels labels={labels} y={height - 8} />
        </svg>
        {active != null && current && (
          <ChartTooltip
            x={center(active)}
            containerWidth={width}
            heading={compared ? undefined : formatDate(current.date)}
            rows={[
              {
                color: CHART.bar,
                label: compared ? formatDate(current.date) : label,
                value: formatValue(current.value),
              },
              ...(compared && current.comparison != null
                ? [
                    {
                      color: CHART.comparison,
                      label: formatDate(comparisonDates?.[active] ?? ""),
                      value: formatValue(current.comparison),
                    },
                  ]
                : []),
            ]}
          />
        )}
        <Box visuallyHidden aria-live="polite">
          {current ? `${formatDate(current.date)}: ${formatValue(current.value)}` : ""}
        </Box>
      </Box>
      <ChartLegend
        items={[
          { color: CHART.bar, label },
          ...(compared && comparisonLabel
            ? [{ color: CHART.comparison, label: comparisonLabel }]
            : []),
        ]}
      />
    </BlockStack>
  );
}

import { useState } from "react";
import { BlockStack, Box, InlineStack, Text } from "@xco-agency/corex-ui";
import { CHART } from "../constants";
import type { DonutChartPropsType } from "../types";
import { SeriesMarker } from "./ChartTooltip";

/**
 * Shopify's donut ("Sales by channel"): a ring of slices with the total in
 * its centre and a legend with each slice's value and share, readable
 * without hovering. Hovering a legend row highlights its slice.
 */
export function DonutChart({
  slices,
  total,
  totalLabel,
  ariaLabel,
  size = 160,
}: DonutChartPropsType) {
  const [active, setActive] = useState<string | null>(null);
  const sumValues = slices.reduce((s, slice) => s + Math.max(slice.value, 0), 0);
  const stroke = 18;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const gap = slices.length > 1 ? 2 : 0;
  let offset = 0;
  const colour = (i: number): string =>
    CHART.palette[i % CHART.palette.length] ?? CHART.bar;

  return (
    <InlineStack gap="large-100" alignItems="center" wrap>
      <Box position="relative" style={{ width: size, height: size, flex: "0 0 auto" }}>
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          role="img"
          aria-label={ariaLabel}
          style={{ display: "block", transform: "rotate(-90deg)" }}
        >
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            stroke={CHART.grid}
            strokeWidth={stroke}
          />
          {sumValues > 0 &&
            slices.map((slice, i) => {
              const length = (Math.max(slice.value, 0) / sumValues) * circumference;
              const dash = Math.max(length - gap, 0);
              const element = (
                <circle
                  key={slice.id}
                  data-slice={slice.id}
                  cx={size / 2}
                  cy={size / 2}
                  r={radius}
                  fill="none"
                  stroke={colour(i)}
                  strokeWidth={active === slice.id ? stroke + 4 : stroke}
                  strokeOpacity={active && active !== slice.id ? 0.35 : 1}
                  strokeDasharray={`${dash} ${circumference - dash}`}
                  strokeDashoffset={-offset}
                >
                  <title>{`${slice.label}: ${slice.display}`}</title>
                </circle>
              );
              offset += length;
              return element;
            })}
        </svg>
        <Box
          position="absolute"
          style={{
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            textAlign: "center",
            pointerEvents: "none",
          }}
        >
          <BlockStack gap="small-400" justifyContent="center">
            <Text as="span" variant="headingMd">
              {total}
            </Text>
            <Text as="span" variant="bodySm" color="subdued">
              {totalLabel}
            </Text>
          </BlockStack>
        </Box>
      </Box>
      <Box style={{ flex: "1 1 180px", minWidth: 0 }}>
        <BlockStack gap="small-200">
          {slices.map((slice, i) => (
            <Box
              key={slice.id}
              data-legend-row=""
              onMouseEnter={() => setActive(slice.id)}
              onMouseLeave={() => setActive(null)}
            >
              <InlineStack
                justifyContent="space-between"
                alignItems="center"
                gap="small-100"
                wrap={false}
              >
                <InlineStack gap="small-300" alignItems="center" wrap={false}>
                  <SeriesMarker color={colour(i)} />
                  <Text as="span" variant="bodySm" lineClamp={1}>
                    {slice.label}
                  </Text>
                </InlineStack>
                <InlineStack gap="small-200" alignItems="center" wrap={false}>
                  <Text as="span" variant="bodySm" fontWeight="semibold" numeric>
                    {slice.display}
                  </Text>
                  <Text as="span" variant="bodySm" color="subdued" numeric>
                    {sumValues > 0
                      ? `${Math.round((Math.max(slice.value, 0) / sumValues) * 100)}%`
                      : "0%"}
                  </Text>
                </InlineStack>
              </InlineStack>
            </Box>
          ))}
        </BlockStack>
      </Box>
    </InlineStack>
  );
}

import { BlockStack, Grid, Text } from "@xco-agency/corex-ui";
import { CHART, FUNNEL_BAR_SHARE, FUNNEL_PLOT_HEIGHT } from "../constants";
import type { FunnelChartPropsType } from "../types";
import { ChangeIndicator } from "./ChangeIndicator";

/**
 * Shopify's "Conversion rate breakdown": a column per stage with its label,
 * share and count over it, a solid bar for the stage, and a faded band
 * flowing from each bar's top down to the next one's (the drop-off).
 */
export function FunnelChart({ stages, ariaLabel }: FunnelChartPropsType) {
  const plot = FUNNEL_PLOT_HEIGHT;
  const n = Math.max(stages.length, 1);
  const width = 1000;
  const column = width / n;
  const barWidth = column * FUNNEL_BAR_SHARE;
  const height = (share: number | null) =>
    Math.max(((Math.min(share ?? 0, 100) || 0) / 100) * plot, share ? 2 : 0);

  return (
    <BlockStack gap="small-100">
      <Grid gridTemplateColumns={`repeat(${n}, minmax(0, 1fr))`} gap="small">
        {stages.map((stage) => (
          <BlockStack key={stage.id} gap="small-400">
            <Text
              as="p"
              variant="bodySm"
              color="subdued"
              tooltip={stage.help}
              lineClamp={2}
            >
              {stage.label}
            </Text>
            <Text as="p" variant="headingLg">
              {stage.shareDisplay}
            </Text>
            <Text as="p" variant="bodySm">
              {stage.display}
            </Text>
            <ChangeIndicator pct={stage.change ?? null} />
            {stage.note && (
              <Text as="p" variant="bodySm" color="subdued">
                {stage.note}
              </Text>
            )}
          </BlockStack>
        ))}
      </Grid>
      <svg
        width="100%"
        height={plot}
        viewBox={`0 0 ${width} ${plot}`}
        preserveAspectRatio="none"
        role="img"
        aria-label={ariaLabel}
        style={{ display: "block" }}
      >
        <line
          x1={0}
          x2={width}
          y1={plot - 0.5}
          y2={plot - 0.5}
          stroke={CHART.baseline}
          strokeWidth={1}
          vectorEffect="non-scaling-stroke"
        />
        {stages.map((stage, i) => {
          const x = i * column;
          const h = height(stage.share);
          const next = stages[i + 1];
          return (
            <g key={stage.id} data-stage={stage.id}>
              <title>{`${stage.label}: ${stage.display} (${stage.shareDisplay})`}</title>
              {/* The track the bar would fill at 100%. */}
              <rect
                x={x}
                y={0}
                width={barWidth}
                height={plot}
                fill={CHART.faded}
                fillOpacity={0.45}
              />
              {next && (
                <polygon
                  data-connector=""
                  points={`${x + barWidth},${plot - h} ${x + column},${plot - height(next.share)} ${x + column},${plot} ${x + barWidth},${plot}`}
                  fill={CHART.faded}
                />
              )}
              <rect
                x={x}
                y={plot - h}
                width={barWidth}
                height={h}
                fill={CHART.bar}
                rx={2}
              />
            </g>
          );
        })}
      </svg>
    </BlockStack>
  );
}

